import { useMemo, useState } from 'react';
import {
  Card,
  Chip,
  ChipGroup,
  Stack,
  Inline,
  Text,
  ProgressCircle,
  Badge,
  Pagination,
  EmptyState,
  Button,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over-quota' | 'completed';

interface ProjectSpend {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  'over-quota': 'Превышена квота',
  completed: 'Завершён',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'neutral' | 'danger' | 'info'> = {
  active: 'success',
  paused: 'neutral',
  'over-quota': 'danger',
  completed: 'info',
};

const PROJECTS: ProjectSpend[] = [
  { id: 'proj-1', name: 'Аналитика продаж', quotaPercent: 42, status: 'active' },
  { id: 'proj-2', name: 'Миграция инфраструктуры', quotaPercent: 87, status: 'active' },
  { id: 'proj-3', name: 'Мобильное приложение', quotaPercent: 100, status: 'over-quota' },
  { id: 'proj-4', name: 'CRM интеграция', quotaPercent: 15, status: 'paused' },
  { id: 'proj-5', name: 'Внутренний портал', quotaPercent: 63, status: 'active' },
  { id: 'proj-6', name: 'Пилот ML-рекомендаций', quotaPercent: 100, status: 'over-quota' },
  { id: 'proj-7', name: 'Редизайн лендинга', quotaPercent: 100, status: 'completed' },
  { id: 'proj-8', name: 'Онбординг клиентов', quotaPercent: 28, status: 'paused' },
  { id: 'proj-9', name: 'API-платёжный шлюз', quotaPercent: 71, status: 'active' },
  { id: 'proj-10', name: 'Архив документов', quotaPercent: 100, status: 'completed' },
  { id: 'proj-11', name: 'Поддержка партнёров', quotaPercent: 54, status: 'active' },
  { id: 'proj-12', name: 'Тестовый стенд QA', quotaPercent: 9, status: 'paused' },
];

const ALL_STATUSES: ProjectStatus[] = ['active', 'paused', 'over-quota', 'completed'];
const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveFilters([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeFilters.length === 0) return PROJECTS;
    return PROJECTS.filter((p) => activeFilters.includes(p.status));
  }, [activeFilters]);

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);

  const pageItems = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredProjects.slice(start, start + PAGE_SIZE);
  }, [filteredProjects, currentPage]);

  return (
    <Card padding="lg">
      <Stack gap="md">
        <Text as="h2" size="lg" weight="semibold">
          Расход по проектам
        </Text>

        <ChipGroup aria-label="Фильтры по статусу">
          {ALL_STATUSES.map((status) => (
            <Chip
              key={status}
              selected={activeFilters.includes(status)}
              onClick={() => toggleFilter(status)}
              onDismiss={
                activeFilters.includes(status) ? () => toggleFilter(status) : undefined
              }
            >
              {STATUS_LABELS[status]}
            </Chip>
          ))}
        </ChipGroup>

        {filteredProjects.length === 0 ? (
          <EmptyState
            title="Ничего не найдено"
            description="Под выбранные фильтры не подошёл ни один проект."
            action={<Button onClick={resetFilters}>Сбросить фильтры</Button>}
          />
        ) : (
          <>
            <Stack gap="sm">
              {pageItems.map((project) => (
                <Card key={project.id} padding="md" variant="outlined">
                  <Inline gap="md" align="center" justify="space-between">
                    <Text weight="medium">{project.name}</Text>
                    <Inline gap="md" align="center">
                      <ProgressCircle
                        value={project.quotaPercent}
                        max={100}
                        size="sm"
                        label={`${project.quotaPercent}%`}
                      />
                      <Badge tone={STATUS_TONES[project.status]}>
                        {STATUS_LABELS[project.status]}
                      </Badge>
                    </Inline>
                  </Inline>
                </Card>
              ))}
            </Stack>

            {totalPages > 1 && (
              <Pagination
                page={currentPage}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            )}
          </>
        )}
      </Stack>
    </Card>
  );
}

